fun Modifier.selectionOutline(selected: Boolean) = drawWithCache {
    val stroke = Stroke(width = 2.dp.toPx())
    onDrawWithContent {
        drawContent()
        if (selected) drawRect(Color.Cyan, style = stroke)
    }
}

