Modifier.pointerInput(itemId) {
    detectDragGesturesAfterLongPress(
        onDragStart = { onDragStarted(itemId) },
        onDrag = { change, amount ->
            change.consume()
            onDragBy(amount)
        },
        onDragEnd = onDragEnded
    )
}

