private val avatarModifier = Modifier
    .size(40.dp)
    .clip(CircleShape)

@Composable
fun AvatarList(users: List<User>) {
    LazyColumn { items(users, key = { it.id }) { Avatar(it, avatarModifier) } }
}

data class OutlineElement(val color: Color) : ModifierNodeElement<OutlineNode>() {
    override fun create() = OutlineNode(color)
    override fun update(node: OutlineNode) { node.color = color }
}

class OutlineNode(var color: Color) : Modifier.Node(), DrawModifierNode {
    override fun ContentDrawScope.draw() {
        drawContent()
        drawRect(color, style = Stroke(1.dp.toPx()))
    }
}

fun Modifier.outline(color: Color) = this then OutlineElement(color)
